(7213521, 1111890, 30861, '<td valign="top">My kind of minimalism. Love how you thumb your nose at the "no reflections" clause by including the reflected figure :-)</td>', 'My kind of minimalism. Love how you thumb your nose at the "no reflections" clause by including the reflected figure :-)', '2014-05-07 01:40:13.000000', NULL, 1),
(7213529, 1111973, 108069, '<td valign="top">Excellent mood. The cranes(?) and structures in the distance create a surreal sense of scale. Great stuff.</td>', 'Excellent mood. The cranes(?) and structures in the distance create a surreal sense of scale. Great stuff.', '2014-05-07 01:56:22.000000', NULL, 1),
(7213531, 1111980, 108069, '<td valign="top">A very well scouted out shot. Perfect for this. Great tones and contrast. Very well done.</td>', 'A very well scouted out shot. Perfect for this. Great tones and contrast. Very well done.', '2014-05-07 01:57:52.000000', NULL, 1),
(7213532, 1111523, 108069, '<td valign="top">I''m bothered by this photo, as I''ve already handed out a favorite. Well there''ll have to be two. I''m assuming this is lens-cap-long-exposure-flip-the-camera trickery? Whatever it is it''s powerful and mysterious, and I wish it were 20 times larger, taking up a wall. Sweet tones. Excellent stuff.</td>', 'I''m bothered by this photo, as I''ve already handed out a favorite. Well there''ll have to be two. I''m assuming this is lens-cap-long-exposure-flip-the-camera trickery? Whatever it is it''s powerful and mysterious, and I wish it were 20 times larger, taking up a wall. Sweet tones. Excellent stuff.', '2014-05-07 02:02:23.000000', NULL, 1),
(7213572, 1111734, 117474, '<td valign="top">The light around the ''branches'' (or whatever they''re called; the radial extensions from the centre) is really nice.</td>', 'The light around the ''branches'' (or whatever they''re called; the radial extensions from the centre) is really nice.', '2014-05-07 04:24:41.000000', NULL, 1),
